// Package monitoring provides Prometheus metrics with standardized naming conventions
// following the RED (Rate, Errors, Duration) and USE (Utilization, Saturation, Errors)
// methodologies for observability best practices.
//
// # Metric Naming Convention
//
// All metrics follow the format: <namespace>_<subsystem>_<name>_<unit>_<suffix>
//
// ## Metric Types and Suffixes
//
//   - Counters: Must end with _total (e.g., http_requests_total)
//   - Gauges: No suffix (e.g., active_connections, memory_usage_bytes)
//   - Histograms: _bucket, _sum, _count suffixes auto-generated by Prometheus client
//   - Summaries: _sum, _count suffixes auto-generated
//
// ## RED Method (Request-focused metrics)
//
// For each service endpoint or operation:
//   - Rate: <service>_requests_total - Total requests
//   - Errors: <service>_errors_total - Total errors
//   - Duration: <service>_duration_seconds - Request latency
//
// ## USE Method (Resource-focused metrics)
//
// For each resource (CPU, memory, connections, etc.):
//   - Utilization: <resource>_utilization_percent - Percentage used
//   - Saturation: <resource>_saturation_wait_seconds - Time waiting
//   - Errors: <resource>_errors_total - Error count
//
// ## Cardinality Controls
//
// To prevent metrics explosion:
//   - User IDs: Never use high-cardinality values like user_id as labels
//   - URLs: Normalize URLs to patterns (e.g., /api/v1/users/{id} -> /api/v1/users/:id)
//   - Timestamps: Never include timestamps in metric names or labels
//   - Status codes: Group similar codes (2xx, 4xx, 5xx)
//
// ## Example Usage
//
//	// Initialize metrics with standard names
//	metrics := monitoring.NewStandardMetrics("myapp")
//
//	// Record a request using RED method
//	metrics.RecordRequest("/api/users", "GET", "200", 0.150)
//
//	// Record resource utilization using USE method
//	metrics.SetUtilization("cpu", 75.5)
//	metrics.RecordSaturation("db_connections", 0.020)
//
//	// Safely increment counters with cardinality validation
//	if monitoring.IsValidLabelValue(userRole) {
//	    metrics.RecordEvent("login", "success", userRole)
//	}
package monitoring

import (
	"fmt"
	"regexp"
	"strings"
	"sync"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promauto"
)

// StandardSuffixes defines the required suffixes for each metric type
const (
	// CounterSuffix is the required suffix for all counter metrics
	CounterSuffix = "_total"

	// Base units as per Prometheus best practices
	SecondsUnit    = "_seconds"
	BytesUnit      = "_bytes"
	PercentUnit    = "_percent"
	PercentUnitAlt = "_ratio" // Alternative to percent
)

// Cardinality limits to prevent metrics explosion
const (
	// MaxLabelValuesPerLabel is the maximum number of unique values for a single label
	MaxLabelValuesPerLabel = 100

	// MaxLabelNameLength is the maximum length for label names
	MaxLabelNameLength = 1024

	// MaxLabelValueLength is the maximum length for label values
	MaxLabelValueLength = 1024

	// MaxMetricNameLength is the maximum length for metric names
	MaxMetricNameLength = 1024
)

// Reserved label names that should not be used
var ReservedLabelNames = map[string]bool{
	"__name__": true, // Prometheus internal
	"le":       true, // Histogram bucket
	"instance": true, // Prometheus reserved
	"job":      true, // Prometheus reserved
}

// ValidLabelNameRegex matches valid Prometheus label names
// Must match [a-zA-Z_][a-zA-Z0-9_]*
var ValidLabelNameRegex = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)

// ValidMetricNameRegex matches valid Prometheus metric names
// Must match [a-zA-Z_:][a-zA-Z0-9_:]*
var ValidMetricNameRegex = regexp.MustCompile(`^[a-zA-Z_:][a-zA-Z0-9_:]*$`)

// HighCardinalityPatterns contains regex patterns for high-cardinality values
// that should not be used as label values
var HighCardinalityPatterns = []*regexp.Regexp{
	regexp.MustCompile(`^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$`), // UUID
	regexp.MustCompile(`^[0-9a-f]{64}$`),                                                 // SHA256 hash
	regexp.MustCompile(`^[0-9a-f]{40}$`),                                                 // SHA1 hash
	regexp.MustCompile(`^[0-9a-f]{32}$`),                                                 // MD5 hash
	regexp.MustCompile(`^\d{4}-\d{2}-\d{2}`),                                             // ISO dates
	regexp.MustCompile(`^\d{10,}$`),                                                      // Numeric IDs (10+ digits)
}

// LabelCardinalityTracker tracks cardinality of label values
// to prevent metrics explosion
type LabelCardinalityTracker struct {
	mu     sync.RWMutex
	labels map[string]map[string]struct{} // label_name -> set of values
}

// NewLabelCardinalityTracker creates a new cardinality tracker
func NewLabelCardinalityTracker() *LabelCardinalityTracker {
	return &LabelCardinalityTracker{
		labels: make(map[string]map[string]struct{}),
	}
}

// TrackValue tracks a label value and returns whether it's within cardinality limits
func (ct *LabelCardinalityTracker) TrackValue(labelName, value string) bool {
	ct.mu.Lock()
	defer ct.mu.Unlock()

	if ct.labels[labelName] == nil {
		ct.labels[labelName] = make(map[string]struct{})
	}

	// Check if we already have this value
	if _, exists := ct.labels[labelName][value]; exists {
		return true // Value already tracked, within limits
	}

	// Check cardinality limit
	if len(ct.labels[labelName]) >= MaxLabelValuesPerLabel {
		return false // Cardinality limit exceeded
	}

	ct.labels[labelName][value] = struct{}{}
	return true
}

// GetCardinality returns the current cardinality for a label
func (ct *LabelCardinalityTracker) GetCardinality(labelName string) int {
	ct.mu.RLock()
	defer ct.mu.RUnlock()

	if ct.labels[labelName] == nil {
		return 0
	}
	return len(ct.labels[labelName])
}

// Reset clears all tracked values
func (ct *LabelCardinalityTracker) Reset() {
	ct.mu.Lock()
	defer ct.mu.Unlock()
	ct.labels = make(map[string]map[string]struct{})
}

// StandardMetrics provides standardized metrics following RED/USE methodologies
type StandardMetrics struct {
	namespace   string
	cardinality *LabelCardinalityTracker

	// RED Metrics
	requestDuration prometheus.HistogramVec
	requestsTotal   prometheus.CounterVec
	errorsTotal     prometheus.CounterVec

	// USE Metrics
	utilizationGauge prometheus.GaugeVec
	saturationGauge  prometheus.GaugeVec
	resourceErrors   prometheus.CounterVec
}

// NewStandardMetrics creates a new StandardMetrics instance with standardized naming
func NewStandardMetrics(namespace string) *StandardMetrics {
	return &StandardMetrics{
		namespace:   namespace,
		cardinality: NewLabelCardinalityTracker(),
		requestDuration: *promauto.NewHistogramVec(
			prometheus.HistogramOpts{
				Namespace: namespace,
				Name:      "request_duration_seconds",
				Help:      "Request duration in seconds (RED: Duration)",
				Buckets:   prometheus.DefBuckets,
			},
			[]string{"method", "endpoint", "status"},
		),
		requestsTotal: *promauto.NewCounterVec(
			prometheus.CounterOpts{
				Namespace: namespace,
				Name:      "requests_total",
				Help:      "Total number of requests (RED: Rate)",
			},
			[]string{"method", "endpoint", "status"},
		),
		errorsTotal: *promauto.NewCounterVec(
			prometheus.CounterOpts{
				Namespace: namespace,
				Name:      "errors_total",
				Help:      "Total number of errors (RED: Errors)",
			},
			[]string{"method", "endpoint", "error_type"},
		),
		utilizationGauge: *promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Namespace: namespace,
				Name:      "utilization_percent",
				Help:      "Resource utilization percentage (USE: Utilization)",
			},
			[]string{"resource"},
		),
		saturationGauge: *promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Namespace: namespace,
				Name:      "saturation_wait_seconds",
				Help:      "Time waiting for resource in seconds (USE: Saturation)",
			},
			[]string{"resource"},
		),
		resourceErrors: *promauto.NewCounterVec(
			prometheus.CounterOpts{
				Namespace: namespace,
				Name:      "resource_errors_total",
				Help:      "Total resource errors (USE: Errors)",
			},
			[]string{"resource", "error_type"},
		),
	}
}

// RecordRequest records a request with RED metrics
func (sm *StandardMetrics) RecordRequest(method, endpoint, status string, duration time.Duration) {
	// Normalize endpoint to prevent high cardinality
	normalizedEndpoint := NormalizeEndpoint(endpoint)

	sm.requestsTotal.WithLabelValues(method, normalizedEndpoint, status).Inc()
	sm.requestDuration.WithLabelValues(method, normalizedEndpoint, status).Observe(duration.Seconds())

	if strings.HasPrefix(status, "4") || strings.HasPrefix(status, "5") {
		sm.errorsTotal.WithLabelValues(method, normalizedEndpoint, status).Inc()
	}
}

// SetUtilization sets resource utilization percentage (USE methodology)
func (sm *StandardMetrics) SetUtilization(resource string, percent float64) {
	sm.utilizationGauge.WithLabelValues(resource).Set(percent)
}

// RecordSaturation records resource saturation wait time (USE methodology)
func (sm *StandardMetrics) RecordSaturation(resource string, waitTime time.Duration) {
	sm.saturationGauge.WithLabelValues(resource).Set(waitTime.Seconds())
}

// RecordResourceError records a resource error (USE methodology)
func (sm *StandardMetrics) RecordResourceError(resource, errorType string) {
	sm.resourceErrors.WithLabelValues(resource, errorType).Inc()
}

// NormalizeEndpoint normalizes URL endpoints to prevent high cardinality
// Replaces dynamic path segments with placeholders
//
// Examples:
//
//	/api/v1/users/12345 -> /api/v1/users/:id
//	/api/v1/users/abc-123/posts -> /api/v1/users/:id/posts
func NormalizeEndpoint(endpoint string) string {
	if endpoint == "" {
		return "/"
	}

	// Remove query parameters
	if idx := strings.Index(endpoint, "?"); idx != -1 {
		endpoint = endpoint[:idx]
	}

	// Split path
	parts := strings.Split(endpoint, "/")

	// Normalize each part
	for i, part := range parts {
		if part == "" {
			continue
		}

		// Check if it looks like an ID (numeric or UUID-like)
		if isIDLike(part) {
			parts[i] = ":id"
		}
	}

	return strings.Join(parts, "/")
}

// isIDLike checks if a string looks like an ID
func isIDLike(s string) bool {
	// Check if it's numeric
	if isNumeric(s) {
		return len(s) >= 3 // IDs are usually 3+ digits
	}

	// Check if it matches UUID patterns
	for _, pattern := range HighCardinalityPatterns {
		if pattern.MatchString(s) {
			return true
		}
	}

	return false
}

// isNumeric checks if a string is numeric
func isNumeric(s string) bool {
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return s != ""
}

// ValidateMetricName validates a metric name according to Prometheus conventions
func ValidateMetricName(name string) error {
	if name == "" {
		return fmt.Errorf("metric name cannot be empty")
	}

	if len(name) > MaxMetricNameLength {
		return fmt.Errorf("metric name too long: %d > %d", len(name), MaxMetricNameLength)
	}

	if !ValidMetricNameRegex.MatchString(name) {
		return fmt.Errorf("metric name contains invalid characters: %s", name)
	}

	return nil
}

// ValidateLabelName validates a label name
func ValidateLabelName(name string) error {
	if name == "" {
		return fmt.Errorf("label name cannot be empty")
	}

	if len(name) > MaxLabelNameLength {
		return fmt.Errorf("label name too long: %d > %d", len(name), MaxLabelNameLength)
	}

	if ReservedLabelNames[name] {
		return fmt.Errorf("label name is reserved: %s", name)
	}

	if !ValidLabelNameRegex.MatchString(name) {
		return fmt.Errorf("label name contains invalid characters: %s", name)
	}

	return nil
}

// ValidateLabelValue validates a label value
func ValidateLabelValue(value string) error {
	if len(value) > MaxLabelValueLength {
		return fmt.Errorf("label value too long: %d > %d", len(value), MaxLabelValueLength)
	}

	return nil
}

// IsValidLabelValue checks if a value is safe to use as a label value
// Returns false for high-cardinality values like UUIDs, hashes, timestamps
func IsValidLabelValue(value string) bool {
	// Check length
	if len(value) > MaxLabelValueLength {
		return false
	}

	// Check against high-cardinality patterns
	for _, pattern := range HighCardinalityPatterns {
		if pattern.MatchString(value) {
			return false
		}
	}

	return true
}

// NormalizeStatusCode groups HTTP status codes into categories
// to prevent high cardinality while maintaining observability
//
// 2xx -> 2xx
// 4xx -> 4xx
// 5xx -> 5xx
func NormalizeStatusCode(code int) string {
	switch {
	case code >= 200 && code < 300:
		return "2xx"
	case code >= 300 && code < 400:
		return "3xx"
	case code >= 400 && code < 500:
		return "4xx"
	case code >= 500 && code < 600:
		return "5xx"
	default:
		return fmt.Sprintf("%d", code)
	}
}

// StandardMetricLabels returns a map of standard labels to use for consistent
// metrics across the application
var StandardMetricLabels = map[string]string{
	"method":     "HTTP method or operation type",
	"endpoint":   "API endpoint or operation name",
	"status":     "Response status code category (2xx, 4xx, 5xx)",
	"error_type": "Type of error for categorization",
	"resource":   "Resource name (cpu, memory, db_connections, etc.)",
	"tenant_id":  "Tenant identifier (low cardinality)",
	"component":  "Service component name",
	"version":    "Application version",
}
